export function hierarchicalOrchestration(agents) {
  const pubSubSystem = createPubSubSystem();
  const escalationPaths = createEscalationPaths(agents);

  agents.forEach(agent => {
    agent.on('disagreement', (issue) => {
      const resolved = pubSubSystem.publish(issue);
      if (!resolved) {
        escalateIssue(issue, escalationPaths);
      }
    });
  });

  function createPubSubSystem() {
    const topics = {};
    return {
      publish: (issue) => {
        const topic = topics[issue.topic];
        if (topic) {
          return topic.resolve(issue);
        }
        return false;
      },
      subscribe: (topicName, resolver) => {
        topics[topicName] = { resolve: resolver };
      }
    };
  }

  function createEscalationPaths(agents) {
    return agents.map(agent => ({
      agent,
      escalate: (issue) => agent.resolve(issue)
    }));
  }

  function escalateIssue(issue, paths) {
    for (const path of paths) {
      if (path.escalate(issue)) {
        return true;
      }
    }
    return false;
  }
}